/* ================== PARAMETERS (SSMS) ================== */
DECLARE @FromDate DATE = '2026-01-01';
DECLARE @ToDate   DATE = '2026-12-31';

SELECT     /* 0. Branch Info */    ISNULL(T2.[BPLName], N'Trụ sở chính') AS [Branch Name],    /* 1. Business Partner & Remarks */    T1.[CardCode] AS [Vendor Code],    T1.[CardName] AS [Vendor Name],    T1.[Comments] AS [PO Remarks],    /* 2. Item & UoM Info */    T0.[ItemCode] AS [Item Code],    T0.[Dscription] AS [Item Description],    T0.[unitMsr] AS [Purchasing UoM],      T0.[unitMsr2] AS [Inventory UoM],     /* 3. Purchase Order (PO) */    T1.[DocNum] AS [PO Doc. No.],    T1.[NumAtCard] AS [Vendor Ref. No.],    T1.[DocDate] AS [PO Posting Date],    T0.[ShipDate] AS [Planned Delivery Date],    T0.[Quantity] AS [Ordered Qty],        T1.[DocCur] AS [Currency],    T0.[Price] AS [Unit Price],     T0.[VatPrcnt] AS [VAT %],       CASE WHEN T1.[DocCur] = 'VND' THEN T0.[LineTotal] ELSE T0.[TotalFrgn] END AS [PO Line Total],    CASE WHEN T1.[DocCur] = 'VND' THEN T0.[VatSum] ELSE T0.[VatSumFrgn] END AS [PO VAT Amount],    /* 4. Goods Receipt PO (GRPO) */    ISNULL(GRPO_Std.[DocNum], GRPO_Res.[DocNum]) AS [GRPO Doc. No.],    ISNULL(GRPO_Std.[DocDate], GRPO_Res.[DocDate]) AS [GRPO Posting Date],    ISNULL(GRPO_Std.[Quantity], GRPO_Res.[Quantity]) AS [Received Qty],    ISNULL(GRPO_Std.[WhsCode], GRPO_Res.[WhsCode]) AS [Whs Code],    ISNULL(GRPO_Std.[U_LCDone], GRPO_Res.[U_LCDone]) AS [LC Done], /* ĐÃ THÊM CỘT U_LCDone TẠI ĐÂY */    /* 5. A/P Invoice */    ISNULL(AP_Std.[DocNum], AP_Dir.[DocNum]) AS [AP Inv. Doc. No.],    ISNULL(AP_Std.[NumAtCard], AP_Dir.[NumAtCard]) AS [AP Inv. Vendor Ref.],    ISNULL(AP_Std.[DocDate], AP_Dir.[DocDate]) AS [AP Inv. Posting Date],         ISNULL(        CASE WHEN AP_Std.[DocCur] = 'VND' THEN AP_Std.[LineTotal] ELSE AP_Std.[TotalFrgn] END,        CASE WHEN AP_Dir.[DocCur] = 'VND' THEN AP_Dir.[LineTotal] ELSE AP_Dir.[TotalFrgn] END    ) AS [AP Inv. Line Total],    ISNULL(        CASE WHEN AP_Std.[DocCur] = 'VND' THEN AP_Std.[VatSum] ELSE AP_Std.[VatSumFrgn] END,        CASE WHEN AP_Dir.[DocCur] = 'VND' THEN AP_Dir.[VatSum] ELSE AP_Dir.[VatSumFrgn] END    ) AS [AP Inv. VAT Amount],        /* 6. Document Flow Status */    CASE         WHEN AP_Std.[DocEntry] IS NOT NULL THEN 'PO -> GRPO -> AP Invoice'        WHEN GRPO_Res.[DocEntry] IS NOT NULL THEN 'PO -> AP Reserve -> GRPO'        WHEN AP_Dir.[DocEntry] IS NOT NULL THEN 'PO -> AP Invoice (Direct)'        WHEN GRPO_Std.[DocEntry] IS NOT NULL THEN 'PO -> GRPO (Pending AP)'        ELSE 'PO Only (Open)'    END AS [Document Flow]FROM [dbo].[POR1] T0 INNER JOIN [dbo].[OPOR] T1 ON T0.[DocEntry] = T1.[DocEntry]LEFT JOIN [dbo].[OBPL] T2 ON T1.[BPLId] = T2.[BPLId]/* =========================================================   NHÁNH 1: LUỒNG CHUẨN (Thêm U_LCDone vào Subquery)========================================================= */LEFT JOIN (    SELECT D1.DocEntry, D1.LineNum, D1.BaseEntry, D1.BaseLine, D1.BaseType, D1.Quantity, D1.WhsCode, D0.DocNum, D0.DocDate, D0.U_LCDone    FROM PDN1 D1 INNER JOIN OPDN D0 ON D1.DocEntry = D0.DocEntry WHERE D0.CANCELED = 'N') GRPO_Std ON GRPO_Std.BaseEntry = T0.DocEntry AND GRPO_Std.BaseLine = T0.LineNum AND GRPO_Std.BaseType = 22 LEFT JOIN (    SELECT D1.DocEntry, D1.LineNum, D1.BaseEntry, D1.BaseLine, D1.BaseType, D1.LineTotal, D1.TotalFrgn, D1.VatSum, D1.VatSumFrgn, D0.DocNum, D0.DocDate, D0.NumAtCard, D0.DocCur    FROM PCH1 D1 INNER JOIN OPCH D0 ON D1.DocEntry = D0.DocEntry WHERE D0.CANCELED = 'N') AP_Std ON AP_Std.BaseEntry = GRPO_Std.DocEntry AND AP_Std.BaseLine = GRPO_Std.LineNum AND AP_Std.BaseType = 20/* =========================================================   NHÁNH 2: LUỒNG TRỰC TIẾP / BẢO LƯU (Thêm U_LCDone vào Subquery)========================================================= */LEFT JOIN (    SELECT D1.DocEntry, D1.LineNum, D1.BaseEntry, D1.BaseLine, D1.BaseType, D1.LineTotal, D1.TotalFrgn, D1.VatSum, D1.VatSumFrgn, D0.DocNum, D0.DocDate, D0.NumAtCard, D0.DocCur    FROM PCH1 D1 INNER JOIN OPCH D0 ON D1.DocEntry = D0.DocEntry WHERE D0.CANCELED = 'N') AP_Dir ON AP_Dir.BaseEntry = T0.DocEntry AND AP_Dir.BaseLine = T0.LineNum AND AP_Dir.BaseType = 22LEFT JOIN (    SELECT D1.DocEntry, D1.LineNum, D1.BaseEntry, D1.BaseLine, D1.BaseType, D1.Quantity, D1.WhsCode, D0.DocNum, D0.DocDate, D0.U_LCDone    FROM PDN1 D1 INNER JOIN OPDN D0 ON D1.DocEntry = D0.DocEntry WHERE D0.CANCELED = 'N') GRPO_Res ON GRPO_Res.BaseEntry = AP_Dir.DocEntry AND GRPO_Res.BaseLine = AP_Dir.LineNum AND GRPO_Res.BaseType = 18WHERE T1.[DocDate] >= @FromDate AND T1.[DocDate] <= @ToDate AND T1.[CANCELED] = 'N' ORDER BY T1.[DocNum], T0.[LineNum]